package lest.dev.UserService.adapter.input.dto.response;

import java.time.LocalDateTime;
import java.util.List;

public class UserAccessControlResponse {
    private String role;
    private List<String> scopes;
    private UserMfaStatusResponse mfaStatus;
    private String accountStatus;
    private LocalDateTime lastLoginAttempt;

    public UserAccessControlResponse() {}

    public UserAccessControlResponse(String role, List<String> scopes, UserMfaStatusResponse mfaStatus, String accountStatus, LocalDateTime lastLoginAttempt) {
        this.role = role;
        this.scopes = scopes;
        this.mfaStatus = mfaStatus;
        this.accountStatus = accountStatus;
        this.lastLoginAttempt = lastLoginAttempt;
    }

    public String getRole() { return role; }
    public void setRole(String role) { this.role = role; }
    public List<String> getScopes() { return scopes; }
    public void setScopes(List<String> scopes) { this.scopes = scopes; }
    public UserMfaStatusResponse getMfaStatus() { return mfaStatus; }
    public void setMfaStatus(UserMfaStatusResponse mfaStatus) { this.mfaStatus = mfaStatus; }
    public String getAccountStatus() { return accountStatus; }
    public void setAccountStatus(String accountStatus) { this.accountStatus = accountStatus; }
    public LocalDateTime getLastLoginAttempt() { return lastLoginAttempt; }
    public void setLastLoginAttempt(LocalDateTime lastLoginAttempt) { this.lastLoginAttempt = lastLoginAttempt; }
}

package lest.dev.UserService.adapter.input.dto.response;

import java.time.LocalDateTime;

public class UserComplianceResponse {
    private String kycStatus;
    private boolean isPep;
    private String regulatoryRegion;
    private UserTermsAcceptedResponse termsAccepted;
    private boolean dataRetentionConsent;
    private LocalDateTime lastRiskAssessment;

    public UserComplianceResponse() {}

    public UserComplianceResponse(String kycStatus, boolean isPep, String regulatoryRegion, UserTermsAcceptedResponse termsAccepted, boolean dataRetentionConsent, LocalDateTime lastRiskAssessment) {
        this.kycStatus = kycStatus;
        this.isPep = isPep;
        this.regulatoryRegion = regulatoryRegion;
        this.termsAccepted = termsAccepted;
        this.dataRetentionConsent = dataRetentionConsent;
        this.lastRiskAssessment = lastRiskAssessment;
    }

    public String getKycStatus() { return kycStatus; }
    public void setKycStatus(String kycStatus) { this.kycStatus = kycStatus; }
    public boolean isPep() { return isPep; }
    public void setPep(boolean pep) { isPep = pep; }
    public String getRegulatoryRegion() { return regulatoryRegion; }
    public void setRegulatoryRegion(String regulatoryRegion) { this.regulatoryRegion = regulatoryRegion; }
    public UserTermsAcceptedResponse getTermsAccepted() { return termsAccepted; }
    public void setTermsAccepted(UserTermsAcceptedResponse termsAccepted) { this.termsAccepted = termsAccepted; }
    public boolean isDataRetentionConsent() { return dataRetentionConsent; }
    public void setDataRetentionConsent(boolean dataRetentionConsent) { this.dataRetentionConsent = dataRetentionConsent; }
    public LocalDateTime getLastRiskAssessment() { return lastRiskAssessment; }
    public void setLastRiskAssessment(LocalDateTime lastRiskAssessment) { this.lastRiskAssessment = lastRiskAssessment; }
}

package lest.dev.UserService.adapter.input.dto.response;

import java.math.BigDecimal;

public class UserFinancialProfileResponse {
    private String baseCurrency;
    private BigDecimal monthlyIncome;
    private String riskScore;
    private UserSpendingLimitsResponse spendingLimits;
    private String investmentProfile;

    public UserFinancialProfileResponse() {}

    public UserFinancialProfileResponse(String baseCurrency, BigDecimal monthlyIncome, String riskScore, UserSpendingLimitsResponse spendingLimits, String investmentProfile) {
        this.baseCurrency = baseCurrency;
        this.monthlyIncome = monthlyIncome;
        this.riskScore = riskScore;
        this.spendingLimits = spendingLimits;
        this.investmentProfile = investmentProfile;
    }

    public String getBaseCurrency() { return baseCurrency; }
    public void setBaseCurrency(String baseCurrency) { this.baseCurrency = baseCurrency; }
    public BigDecimal getMonthlyIncome() { return monthlyIncome; }
    public void setMonthlyIncome(BigDecimal monthlyIncome) { this.monthlyIncome = monthlyIncome; }
    public String getRiskScore() { return riskScore; }
    public void setRiskScore(String riskScore) { this.riskScore = riskScore; }
    public UserSpendingLimitsResponse getSpendingLimits() { return spendingLimits; }
    public void setSpendingLimits(UserSpendingLimitsResponse spendingLimits) { this.spendingLimits = spendingLimits; }
    public String getInvestmentProfile() { return investmentProfile; }
    public void setInvestmentProfile(String investmentProfile) { this.investmentProfile = investmentProfile; }
}

package lest.dev.UserService.adapter.input.dto.response;

public class UserMfaStatusResponse {
    private boolean enabled;
    private String method;

    public UserMfaStatusResponse() {}

    public UserMfaStatusResponse(boolean enabled, String method) {
        this.enabled = enabled;
        this.method = method;
    }

    public boolean isEnabled() { return enabled; }
    public void setEnabled(boolean enabled) { this.enabled = enabled; }
    public String getMethod() { return method; }
    public void setMethod(String method) { this.method = method; }
}

package lest.dev.UserService.adapter.input.dto.response;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.UUID;

public class UserResponse {
    private UUID userId;
    private String name;
    private String taxId;
    private LocalDate birthDate;
    private String email;
    private String phone;
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;
    private UserComplianceResponse compliance;
    private UserFinancialProfileResponse financialProfile;
    private UserAccessControlResponse accessControl;

    public UserResponse() {}

    public UserResponse(UUID userId, String name, String taxId, LocalDate birthDate, String email, String phone, LocalDateTime createdAt, LocalDateTime updatedAt, UserComplianceResponse compliance, UserFinancialProfileResponse financialProfile, UserAccessControlResponse accessControl) {
        this.userId = userId;
        this.name = name;
        this.taxId = taxId;
        this.birthDate = birthDate;
        this.email = email;
        this.phone = phone;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
        this.compliance = compliance;
        this.financialProfile = financialProfile;
        this.accessControl = accessControl;
    }

    public UUID getUserId() { return userId; }
    public void setUserId(UUID userId) { this.userId = userId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getTaxId() { return taxId; }
    public void setTaxId(String taxId) { this.taxId = taxId; }
    public LocalDate getBirthDate() { return birthDate; }
    public void setBirthDate(LocalDate birthDate) { this.birthDate = birthDate; }
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    public String getPhone() { return phone; }
    public void setPhone(String phone) { this.phone = phone; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
    public UserComplianceResponse getCompliance() { return compliance; }
    public void setCompliance(UserComplianceResponse compliance) { this.compliance = compliance; }
    public UserFinancialProfileResponse getFinancialProfile() { return financialProfile; }
    public void setFinancialProfile(UserFinancialProfileResponse financialProfile) { this.financialProfile = financialProfile; }
    public UserAccessControlResponse getAccessControl() { return accessControl; }
    public void setAccessControl(UserAccessControlResponse accessControl) { this.accessControl = accessControl; }
}

package lest.dev.UserService.adapter.input.dto.response;

